from pathlib import Path
from datetime import datetime
import base64
import json
import shutil
import sqlite3
import subprocess
import sys
import py_compile

ROOT = Path.cwd()
REQUIRED = [
    ROOT / "src/enrichment/profiles.py",
    ROOT / "src/scoring/research_scoring.py",
    ROOT / "data/clinics.sqlite3",
]

missing = [str(p) for p in REQUIRED if not p.exists()]
if missing:
    print("エラー：clinic-list-filter-complete フォルダで実行してください。")
    print("見つからないファイル:")
    for p in missing:
        print(" -", p)
    raise SystemExit(1)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup = ROOT / ("code_backup_research_v252_" + stamp)
backup.mkdir(parents=True, exist_ok=False)

PAYLOADS = {
    "src/enrichment/profiles.py": '',
    "verify_research_v252.py": '',
    "rerun_latest_hp_job_v252.py": '',
    "export_research_v252_results.py": '',
}

targets = [ROOT / rel for rel in PAYLOADS]
for p in targets:
    if p.exists():
        dst = backup / p.relative_to(ROOT)
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, dst)

try:
    for rel, encoded in PAYLOADS.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))

    for rel in PAYLOADS:
        if rel.endswith(".py"):
            py_compile.compile(str(ROOT / rel), doraise=True)

    (ROOT / "VERSION_RESEARCH").write_text("2.5.2-research\n", encoding="utf-8")

except Exception as exc:
    print("適用中にエラーが発生したため、バックアップから戻します。")
    for p in targets:
        src = backup / p.relative_to(ROOT)
        if src.exists():
            p.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, p)
    print("エラー:", repr(exc))
    raise SystemExit(1)

print("v25.2 を適用しました。")
print("【変更点】")
print("・院長名が h1〜h6 の見出しにある場合、次の別人物見出しまでを院長本人ブロックとして扱います。")
print("・『特別顧問 新谷弘実』のような空白なし氏名も人物境界として扱います。")
print("・院長本人より前の別医師の年を混ぜにくくしました。")
print("・v25.1 の集客施策ガード、内視鏡ガード、治療カテゴリ、昼枠、HPランク、Maps連携は維持します。")
print("・SQLite / UUID / Maps取込結果 / Comdesk元データは変更しません。")
print("バックアップ:", backup.name)

print("\n=== v25.2 確認テスト ===")
verify = subprocess.run([sys.executable, str(ROOT / "verify_research_v252.py")])
if verify.returncode != 0:
    print("確認テストが失敗しました。再調査は実行していません。")
    raise SystemExit(verify.returncode)

print("\n=== 直前と同じ50件を v25.2 で再調査 ===")
rerun = subprocess.run([sys.executable, str(ROOT / "rerun_latest_hp_job_v252.py")])
if rerun.returncode != 0:
    print("再調査を完了できませんでした。")
    print("アプリが起動中なら Ctrl+C → Y で停止し、")
    print("  .\\.venv\\Scripts\\python.exe .\\rerun_latest_hp_job_v252.py")
    print("を実行してください。")
    raise SystemExit(rerun.returncode)

print("\n=== v25.2 結果CSVを作成 ===")
export = subprocess.run([sys.executable, str(ROOT / "export_research_v252_results.py")])
if export.returncode != 0:
    print("再調査は完了していますがCSV出力だけ失敗しました。")
    print("  .\\.venv\\Scripts\\python.exe .\\export_research_v252_results.py")
    print("を実行してください。")
    raise SystemExit(export.returncode)

# Key-result check from latest research results.
try:
    con = sqlite3.connect(str(ROOT / "data/clinics.sqlite3"))
    con.row_factory = sqlite3.Row

    def latest_result_like(name):
        row = con.execute("""
            SELECT c.clinic_name, r.result_json
            FROM clinics c
            JOIN research_results r ON r.clinic_id=c.id
            WHERE c.clinic_name LIKE ?
            ORDER BY r.rowid DESC
            LIMIT 1
        """, (f"%{name}%",)).fetchone()
        if not row:
            return None, {}
        try:
            data = json.loads(row["result_json"] or "{}")
        except Exception:
            data = {}
        return row["clinic_name"], data

    print("\n=== 重要項目チェック ===")
    clinic, d = latest_result_like("半蔵門胃腸クリニック")
    if clinic:
        print("医院:", clinic)
        print("卒業年:", d.get("graduation_year"))
        print("59歳以下確率:", d.get("age_probability_under_59"))
        print("年齢信頼度:", d.get("age_estimation_confidence"))
        if d.get("graduation_year") == 1982:
            print("半蔵門胃腸クリニック人物分離: PASS")
        else:
            print("半蔵門胃腸クリニック人物分離: 要確認")

    clinic, d = latest_result_like("飯田橋眼科クリニック")
    if clinic:
        names = [x.get("name") for x in d.get("marketing_signals", []) if isinstance(x, dict)]
        print("飯田橋眼科 集客シグナル:", names)
        print("オンライン診療終了ガード:", "PASS" if "オンライン診療" not in names else "要確認")

except Exception as exc:
    print("重要項目チェックだけ実行できませんでした:", repr(exc))

print("\n=== v25.2 再調査まで完了 ===")
print("出力CSV:", (ROOT / "hp_research_results_v252.csv").resolve())
print("このCSVをChatGPTにアップロードしてください。")
